pub type Queue = { items: Vec[Int]; }

fn Queue.new() -> Queue {
  return Queue{ items: Vec[Int]() };
}

fn Queue.enqueue(self: &mut Queue, item: Int) -> Unit {
  self.items.push(item);
}

fn Queue.dequeue(self: &mut Queue) -> Option[Int] {
  if self.items.len() == 0 { return None; }
  let val = self.items[0];
  self.items.remove(0);
  return Some(val);
}

fn main() -> Int {
  var q = Queue.new();
  q.enqueue(10);
  q.enqueue(20);
  q.enqueue(30);
  var sum = 0;
  while true {
    match q.dequeue() {
      Some(n) => { sum = sum + n; }
      None => { break; }
    }
  }
  return sum;
}
